import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 9 章 写文档：报告、方案与白皮书","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md"}'),d={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md"};function o(l,t,i,p,r,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 9 章 写文档：报告、方案与白皮书（易懂版）](../../easy/第9章 写文档：报告、方案与白皮书（易懂版）.md)</p></div><h1 id="第-9-章-写文档-报告、方案与白皮书" tabindex="-1">第 9 章 写文档：报告、方案与白皮书 <a class="header-anchor" href="#第-9-章-写文档-报告、方案与白皮书" aria-label="Permalink to &quot;第 9 章 写文档：报告、方案与白皮书&quot;">​</a></h1><blockquote><p>本章目标：掌握写文档类任务的完整方法论——六步通用流程、大纲先行原则、三类典型场景的实战模板，以及文档写作的红线。<strong>AI 写文档的价值不在&quot;代笔&quot;，而在把写作变成可管理、可核验、可复用的流程。</strong></p></blockquote><h2 id="_9-1-场景-文档是最高频的-ai-任务" tabindex="-1">9.1 场景：文档是最高频的 AI 任务 <a class="header-anchor" href="#_9-1-场景-文档是最高频的-ai-任务" aria-label="Permalink to &quot;9.1 场景：文档是最高频的 AI 任务&quot;">​</a></h2><p>写文档是最高频的 AI 任务，但也最容易&quot;看着像、其实没用&quot;——满篇正确的废话，读者看完不知道该做什么。本章以三个典型场景为例，从流程到红线一次讲透：</p><table tabindex="0"><thead><tr><th>场景</th><th>特点</th><th>关键能力</th></tr></thead><tbody><tr><td><strong>报告</strong></td><td>基于数据说话，结论先行</td><td>读数据、算口径、引证据</td></tr><tr><td><strong>方案</strong></td><td>支撑决策，读者要拍板</td><td>选项对比、推荐逻辑</td></tr><tr><td><strong>长文档</strong></td><td>结构复杂，篇幅长</td><td>大纲先行、分块写作</td></tr></tbody></table><h2 id="_9-2-通用流程-写任何文档都走这六步" tabindex="-1">9.2 通用流程：写任何文档都走这六步 <a class="header-anchor" href="#_9-2-通用流程-写任何文档都走这六步" aria-label="Permalink to &quot;9.2 通用流程：写任何文档都走这六步&quot;">​</a></h2><p>无论写哪种文档，都走这个流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 明确读者与用途（给谁看、看完要做什么决定）</span></span>
<span class="line"><span>2. 收集素材（数据、资料、模板、往期示例）</span></span>
<span class="line"><span>3. 搭结构（大纲先行，你确认）</span></span>
<span class="line"><span>4. 分块写作（每块可检查、可反馈）</span></span>
<span class="line"><span>5. 数据/事实核对（我能查的帮你查）</span></span>
<span class="line"><span>6. 按你的风格润色（记忆里存的偏好）</span></span></code></pre></div><h3 id="_9-2-1-为什么-先出大纲-是铁律" tabindex="-1">9.2.1 为什么&quot;先出大纲&quot;是铁律 <a class="header-anchor" href="#_9-2-1-为什么-先出大纲-是铁律" aria-label="Permalink to &quot;9.2.1 为什么&quot;先出大纲&quot;是铁律&quot;">​</a></h3><p><strong>大纲错了，写一万字也白搭；大纲对了，填充只是时间问题。</strong></p><ul><li>大纲阶段发现问题：改一行字即可；</li><li>正文阶段发现问题：整段重写。</li></ul><p>大纲是你和我之间最低成本的&quot;对齐协议&quot;。<strong>任何超过一页的文档，我都坚持先给大纲。</strong></p><h3 id="_9-2-2-大纲要细到什么程度" tabindex="-1">9.2.2 大纲要细到什么程度 <a class="header-anchor" href="#_9-2-2-大纲要细到什么程度" aria-label="Permalink to &quot;9.2.2 大纲要细到什么程度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>大纲粒度</th><th>效果</th></tr></thead><tbody><tr><td>&quot;写个报告&quot;</td><td>等于没给，各写各的</td></tr><tr><td>&quot;结论→分析→建议&quot;</td><td>结构对了，但内容方向未定</td></tr><tr><td>&quot;1. 结论（3 条核心发现）2. 渠道对比（表）3. 问题归因（3 类）4. 建议（对应结论）&quot;</td><td>✅ 可以开工</td></tr></tbody></table><p><strong>好大纲 = 每个章节都写清了&quot;这块要说什么&quot;。</strong></p><h2 id="_9-3-案例一-一份基于数据的运营报告" tabindex="-1">9.3 案例一：一份基于数据的运营报告 <a class="header-anchor" href="#_9-3-案例一-一份基于数据的运营报告" aria-label="Permalink to &quot;9.3 案例一：一份基于数据的运营报告&quot;">​</a></h2><h3 id="_9-3-1-指令" tabindex="-1">9.3.1 指令 <a class="header-anchor" href="#_9-3-1-指令" aria-label="Permalink to &quot;9.3.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写一份《Q3 运营复盘报告》：</span></span>
<span class="line"><span>- 数据源：data/q3.csv（阅读后使用，不得编造）</span></span>
<span class="line"><span>- 读者：管理层，结论先行</span></span>
<span class="line"><span>- 结构：核心结论 → 分渠道表现 → 问题分析 → 3 条建议</span></span>
<span class="line"><span>- 长度：不超过 3 页</span></span></code></pre></div><h3 id="_9-3-2-我的做法-逐步拆解" tabindex="-1">9.3.2 我的做法（逐步拆解） <a class="header-anchor" href="#_9-3-2-我的做法-逐步拆解" aria-label="Permalink to &quot;9.3.2 我的做法（逐步拆解）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Read data/q3.csv → 搞清字段、时间范围、数据口径</span></span>
<span class="line"><span>   （发现字段含义模糊 → 问你：&quot;新增用户&quot;指注册还是首单？）</span></span>
<span class="line"><span>② 给出大纲 → 你确认 → 开工</span></span>
<span class="line"><span>③ 逐节写作：</span></span>
<span class="line"><span>   - 核心结论：3 条带数字的发现（引用具体数据行）</span></span>
<span class="line"><span>   - 渠道对比：表格 + 环比/同比</span></span>
<span class="line"><span>   - 问题分析：定位到具体渠道/环节</span></span>
<span class="line"><span>   - 建议：每条建议都对应一个结论（可执行、有负责人）</span></span>
<span class="line"><span>④ 交付 → 附&quot;数据来源与口径说明&quot; → 你核验</span></span></code></pre></div><h3 id="_9-3-3-优秀报告-vs-平庸报告" tabindex="-1">9.3.3 优秀报告 vs 平庸报告 <a class="header-anchor" href="#_9-3-3-优秀报告-vs-平庸报告" aria-label="Permalink to &quot;9.3.3 优秀报告 vs 平庸报告&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>平庸报告</th><th>优秀报告</th></tr></thead><tbody><tr><td>结论</td><td>&quot;整体表现一般&quot;</td><td>&quot;转化率环比下降 18%，主要来自渠道 A&quot;</td></tr><tr><td>证据</td><td>无引用</td><td>&quot;见 2.1 节、数据行 34-40&quot;</td></tr><tr><td>建议</td><td>&quot;加强运营&quot;</td><td>&quot;渠道 A 预算下调 30%，转移至 B（测算见附录）&quot;</td></tr><tr><td>可执行性</td><td>谁都能说</td><td>有负责人、有优先级</td></tr></tbody></table><h2 id="_9-4-案例二-一份方案文档" tabindex="-1">9.4 案例二：一份方案文档 <a class="header-anchor" href="#_9-4-案例二-一份方案文档" aria-label="Permalink to &quot;9.4 案例二：一份方案文档&quot;">​</a></h2><h3 id="_9-4-1-写方案的本质" tabindex="-1">9.4.1 写方案的本质 <a class="header-anchor" href="#_9-4-1-写方案的本质" aria-label="Permalink to &quot;9.4.1 写方案的本质&quot;">​</a></h3><p><strong>写方案的关键是决策支持——读者看完要能拍板。</strong> 一篇好方案，不是罗列选项，而是给决策者&quot;最小认知负担&quot;的决策路径。</p><h3 id="_9-4-2-方案结构模板" tabindex="-1">9.4.2 方案结构模板 <a class="header-anchor" href="#_9-4-2-方案结构模板" aria-label="Permalink to &quot;9.4.2 方案结构模板&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景与目标（为什么做、成功标准）</span></span>
<span class="line"><span>→ 现状分析（痛点、约束）</span></span>
<span class="line"><span>→ 方案选项（A/B/C 对比：成本/工期/风险）</span></span>
<span class="line"><span>→ 推荐项与理由（数据说话）</span></span>
<span class="line"><span>→ 实施计划（步骤、里程碑、验收）</span></span>
<span class="line"><span>→ 风险与对策（最坏情况 + 预案）</span></span></code></pre></div><h3 id="_9-4-3-指令要点" tabindex="-1">9.4.3 指令要点 <a class="header-anchor" href="#_9-4-3-指令要点" aria-label="Permalink to &quot;9.4.3 指令要点&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写《XX 系统改造方案》：</span></span>
<span class="line"><span>- 给出 3 个方案并对比（成本/工期/风险，用表格）</span></span>
<span class="line"><span>- 推荐一个并说明理由（为什么不是另外两个）</span></span>
<span class="line"><span>- 附实施步骤（含里程碑）和验收标准</span></span></code></pre></div><h3 id="_9-4-4-方案对比表的黄金结构" tabindex="-1">9.4.4 方案对比表的黄金结构 <a class="header-anchor" href="#_9-4-4-方案对比表的黄金结构" aria-label="Permalink to &quot;9.4.4 方案对比表的黄金结构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>方案 A（稳妥）</th><th>方案 B（均衡）</th><th>方案 C（激进）</th></tr></thead><tbody><tr><td>成本</td><td>低</td><td>中</td><td>高</td></tr><tr><td>工期</td><td>2 周</td><td>4 周</td><td>8 周</td></tr><tr><td>风险</td><td>低</td><td>中</td><td>高</td></tr><tr><td>适用</td><td>快速止血</td><td>推荐 ✅</td><td>长期最优</td></tr></tbody></table><p><strong>推荐理由要写&quot;为什么不是另外两个&quot;</strong>——这是决策者最关心的问题。</p><h2 id="_9-5-案例三-长文档-白皮书-手册-教程" tabindex="-1">9.5 案例三：长文档（白皮书/手册/教程） <a class="header-anchor" href="#_9-5-案例三-长文档-白皮书-手册-教程" aria-label="Permalink to &quot;9.5 案例三：长文档（白皮书/手册/教程）&quot;">​</a></h2><h3 id="_9-5-1-长文档的挑战" tabindex="-1">9.5.1 长文档的挑战 <a class="header-anchor" href="#_9-5-1-长文档的挑战" aria-label="Permalink to &quot;9.5.1 长文档的挑战&quot;">​</a></h3><p>长文档（比如你现在读的这本白皮书）最大的敌人是<strong>失控</strong>：写到第五章发现第一章的结构要改。</p><h3 id="_9-5-2-长文档方法论" tabindex="-1">9.5.2 长文档方法论 <a class="header-anchor" href="#_9-5-2-长文档方法论" aria-label="Permalink to &quot;9.5.2 长文档方法论&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原则</th><th>做法</th></tr></thead><tbody><tr><td>先定骨架</td><td>章节树先行：几篇 → 几章 → 每章讲什么</td></tr><tr><td>再填血肉</td><td>每章独立推进，章与章之间松耦合</td></tr><tr><td>风格统一</td><td>每章同一套格式（目标框/表格/练习）</td></tr><tr><td>交叉引用</td><td>章末&quot;下一章&quot;、文中&quot;见第 X 章&quot;保持导航</td></tr></tbody></table><h3 id="_9-5-3-长文档的检查清单" tabindex="-1">9.5.3 长文档的检查清单 <a class="header-anchor" href="#_9-5-3-长文档的检查清单" aria-label="Permalink to &quot;9.5.3 长文档的检查清单&quot;">​</a></h3><ul><li>[ ] 每章开头有&quot;本章目标&quot;？</li><li>[ ] 每章有练习/可操作步骤？</li><li>[ ] 章与章之间有导航衔接？</li><li>[ ] 术语全文一致（先建术语表）？</li></ul><h2 id="_9-6-文档写作的红线" tabindex="-1">9.6 文档写作的红线 <a class="header-anchor" href="#_9-6-文档写作的红线" aria-label="Permalink to &quot;9.6 文档写作的红线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>红线</th><th>说明</th><th>我的做法</th></tr></thead><tbody><tr><td>❌ 不编数据</td><td>数据要么来自你给的文件，要么标注&quot;待核实&quot;</td><td>引用时带出处</td></tr><tr><td>❌ 不隐瞒不确定性</td><td>拿不准的地方明说</td><td>写&quot;建议核实&quot;</td></tr><tr><td>✅ 保留修订痕迹</td><td>用 Edit 逐轮改，不整篇重写</td><td>你 review diff</td></tr><tr><td>✅ 结构可复用</td><td>好文档 = 好模板 + 好内容</td><td>模板沉淀下来</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">重点</p><p><strong>数据来源不明的数字，一律标注&quot;待核实&quot;，绝不编造。</strong> 一旦编过一次数据，整个文档的可信度就归零。</p></div><h2 id="_9-7-把文档能力沉淀下来" tabindex="-1">9.7 把文档能力沉淀下来 <a class="header-anchor" href="#_9-7-把文档能力沉淀下来" aria-label="Permalink to &quot;9.7 把文档能力沉淀下来&quot;">​</a></h2><p>写文档最大的复用点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模板（结构）→ 存 docs/templates/</span></span>
<span class="line"><span>偏好（风格）→ 存记忆（&quot;结论先行 + 数据引用&quot;）</span></span>
<span class="line"><span>指令（流程）→ 存为 Skill（&quot;写报告&quot;技能）</span></span></code></pre></div><p><strong>下次写同类文档，一句话触发，全流程就位。</strong></p><h2 id="_9-8-练习" tabindex="-1">9.8 练习 <a class="header-anchor" href="#_9-8-练习" aria-label="Permalink to &quot;9.8 练习&quot;">​</a></h2><ol><li>给我一份真实数据文件，让我写一份带结论的报告（先看大纲再动笔）。</li><li>让我按你公司的模板重写一次，比较差异。</li><li>把这份文档的指令模板存入记忆或 docs/templates/。</li><li>用 9.6 的红线清单，检查我产出的文档是否踩线。</li></ol><hr><blockquote><p>小结：AI 写文档的价值不在&quot;代笔&quot;，而在<strong>把写作变成可管理、可核验、可复用的流程</strong>——大纲先行控制方向，分块写作控制质量，模板沉淀控制复用。下一章：写代码。</p></blockquote>`,51)])])}const b=a(d,[["render",o]]);export{u as __pageData,b as default};
